WITH latest AS (SELECT * FROM orders QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY amount DESC, id) = 1) SELECT id, customer_id, store_id, order_date, status, channel, discount, shipping_fee, CASE WHEN status RLIKE '^(COMPLETED|RETURNED)$' THEN 'CORE' WHEN status RLIKE '^(PENDING|CANCELLED)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS status_zone FROM latest ORDER BY status DESC NULLS LAST
